/**
 * Returns a deterministic daily track index based on the local calendar date.
 * Rotates cleanly to a fresh song every calendar day.
 */
export function getDailyTrackIndex(date: Date = new Date()): number {
  const utcDay = Math.floor(
    Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / 86_400_000
  );
  return ((utcDay % VINYL_TRACKS.length) + VINYL_TRACKS.length) % VINYL_TRACKS.length;
}
